import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Class: DisplayValue","description":"","frontmatter":{},"headers":[],"relativePath":"api/helix/classes/DisplayValue.md","filePath":"api/helix/classes/DisplayValue.md"}'),s={name:"api/helix/classes/DisplayValue.md"};function i(n,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">helix</a> / DisplayValue</p><h1 id="class-displayvalue" tabindex="-1">Class: DisplayValue <a class="header-anchor" href="#class-displayvalue" aria-label="Permalink to &quot;Class: DisplayValue&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L92" target="_blank" rel="noreferrer">core/values/display.ts:92</a></p><p>A display <strong>group</strong>: a root member plus child members carried as <code>Passengers</code>, each rendering either a block state (<code>block_display</code>) or an item stack (<code>item_display</code>), and optionally an <code>interaction</code> hitbox riding the root. Renders to the summon data tag - pass it as the <code>nbt</code> arg:</p><p>const d = Display(Block.POLISHED_BASALT.state({ axis: &quot;x&quot; })) .add(Block.WAXED_COPPER_BLOCK, { translation: [-0.5, -3.5, -0.5] }); ctx.summon(&quot;minecraft:block_display&quot;, Pos.rel(0, 10, 0), d);</p><p>Children are kept in a mutable array, so you can build them from a loop and swap blocks programmatically before rendering.</p><h2 id="implements" tabindex="-1">Implements <a class="header-anchor" href="#implements" aria-label="Permalink to &quot;Implements&quot;">​</a></h2><ul><li><a href="./../interfaces/CommandValue.html"><code>CommandValue</code></a></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new DisplayValue</strong>(<code>content</code>, <code>rootTransform?</code>): <code>DisplayValue</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L102" target="_blank" rel="noreferrer">core/values/display.ts:102</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="content" tabindex="-1">content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;content&quot;">​</a></h5><p><a href="./../type-aliases/DisplayContent.html"><code>DisplayContent</code></a></p><h5 id="roottransform" tabindex="-1">rootTransform? <a class="header-anchor" href="#roottransform" aria-label="Permalink to &quot;rootTransform?&quot;">​</a></h5><p><a href="./../interfaces/Transform.html"><code>Transform</code></a> = <code>{}</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>DisplayValue</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="children" tabindex="-1">children <a class="header-anchor" href="#children" aria-label="Permalink to &quot;children&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>children</strong>: <a href="./../interfaces/DisplayChild.html"><code>DisplayChild</code></a>[] = <code>[]</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L93" target="_blank" rel="noreferrer">core/values/display.ts:93</a></p><hr><h3 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to &quot;id&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>static</code> <strong>id</strong>: <code>string</code> = <code>ENTITY.block</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L108" target="_blank" rel="noreferrer">core/values/display.ts:108</a></p><p>The entity id to summon this with (<code>ctx.summon(Display.id, ...)</code>).</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to &quot;Accessors&quot;">​</a></h2><h3 id="exists" tabindex="-1">exists <a class="header-anchor" href="#exists" aria-label="Permalink to &quot;exists&quot;">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to &quot;Get Signature&quot;">​</a></h4><blockquote><p><strong>get</strong> <strong>exists</strong>(): <a href="./../interfaces/EntityCondition.html"><code>EntityCondition</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L252" target="_blank" rel="noreferrer">core/values/display.ts:252</a></p><p>Condition: the group is currently spawned.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h5><p><a href="./../interfaces/EntityCondition.html"><code>EntityCondition</code></a></p><hr><h3 id="notexist" tabindex="-1">notExist <a class="header-anchor" href="#notexist" aria-label="Permalink to &quot;notExist&quot;">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to &quot;Get Signature&quot;">​</a></h4><blockquote><p><strong>get</strong> <strong>notExist</strong>(): <a href="./../interfaces/EntityCondition.html"><code>EntityCondition</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L257" target="_blank" rel="noreferrer">core/values/display.ts:257</a></p><p>Condition: the group is not currently spawned.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h5><p><a href="./../interfaces/EntityCondition.html"><code>EntityCondition</code></a></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="add" tabindex="-1">add() <a class="header-anchor" href="#add" aria-label="Permalink to &quot;add()&quot;">​</a></h3><blockquote><p><strong>add</strong>(<code>block</code>, <code>transform?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L123" target="_blank" rel="noreferrer">core/values/display.ts:123</a></p><p>Append a child block display at the given transform.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="block" tabindex="-1">block <a class="header-anchor" href="#block" aria-label="Permalink to &quot;block&quot;">​</a></h5><p><a href="./BlockValue.html"><code>BlockValue</code></a></p><h5 id="transform" tabindex="-1">transform? <a class="header-anchor" href="#transform" aria-label="Permalink to &quot;transform?&quot;">​</a></h5><p><a href="./../interfaces/Transform.html"><code>Transform</code></a> = <code>{}</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="additem" tabindex="-1">addItem() <a class="header-anchor" href="#additem" aria-label="Permalink to &quot;addItem()&quot;">​</a></h3><blockquote><p><strong>addItem</strong>(<code>item</code>, <code>transform?</code>, <code>context?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L132" target="_blank" rel="noreferrer">core/values/display.ts:132</a></p><p>Append a child <strong>item</strong> display - a custom-modelled item is one member instead of the dozens of cubes the same shape costs in blocks.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="item" tabindex="-1">item <a class="header-anchor" href="#item" aria-label="Permalink to &quot;item&quot;">​</a></h5><p><a href="./ItemValue.html"><code>ItemValue</code></a></p><h5 id="transform-1" tabindex="-1">transform? <a class="header-anchor" href="#transform-1" aria-label="Permalink to &quot;transform?&quot;">​</a></h5><p><a href="./../interfaces/Transform.html"><code>Transform</code></a> = <code>{}</code></p><h5 id="context" tabindex="-1">context? <a class="header-anchor" href="#context" aria-label="Permalink to &quot;context?&quot;">​</a></h5><p><a href="./../type-aliases/NbtInput.html"><code>NbtInput</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="at" tabindex="-1">at() <a class="header-anchor" href="#at" aria-label="Permalink to &quot;at()&quot;">​</a></h3><blockquote><p><strong>at</strong>(<code>pos</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L237" target="_blank" rel="noreferrer">core/values/display.ts:237</a></p><p>Set the position this display is summoned at.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="pos" tabindex="-1">pos <a class="header-anchor" href="#pos" aria-label="Permalink to &quot;pos&quot;">​</a></h5><p><code>string</code> | <a href="./PosValue.html"><code>PosValue</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="boundsmin" tabindex="-1">boundsMin() <a class="header-anchor" href="#boundsmin" aria-label="Permalink to &quot;boundsMin()&quot;">​</a></h3><blockquote><p><strong>boundsMin</strong>(): <a href="./../type-aliases/Vec3.html"><code>Vec3</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L293" target="_blank" rel="noreferrer">core/values/display.ts:293</a></p><p>The min corner of the model&#39;s block volume in entity-local space - the smallest member translation on each axis. A <code>block_display</code> member with translation <code>t</code> occupies the cube <code>[entity + t, entity + t + 1]</code>, so summoning at <code>worldCorner - boundsMin()</code> makes the model&#39;s lowest block land exactly on <code>worldCorner</code>. Used to overlay a display on the real blocks it stands in for.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../type-aliases/Vec3.html"><code>Vec3</code></a></p><hr><h3 id="boundssize" tabindex="-1">boundsSize() <a class="header-anchor" href="#boundssize" aria-label="Permalink to &quot;boundsSize()&quot;">​</a></h3><blockquote><p><strong>boundsSize</strong>(): <a href="./../type-aliases/Vec3.html"><code>Vec3</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L303" target="_blank" rel="noreferrer">core/values/display.ts:303</a></p><p>The model&#39;s size in whole blocks on each axis (max translation − min + 1). For a model captured from a 2×16×7 structure this returns <code>[2, 16, 7]</code>, the footprint the matching <code>.nbt</code> covers.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../type-aliases/Vec3.html"><code>Vec3</code></a></p><hr><h3 id="brightness" tabindex="-1">brightness() <a class="header-anchor" href="#brightness" aria-label="Permalink to &quot;brightness()&quot;">​</a></h3><blockquote><p><strong>brightness</strong>(<code>block</code>, <code>sky?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L199" target="_blank" rel="noreferrer">core/values/display.ts:199</a></p><p>Pin the rendered light level so the display matches surrounding blocks instead of falling back to dynamic per-entity lighting (which samples one point and usually renders darker / flickers as it moves). Both <code>block</code> and <code>sky</code> are 0–15; <code>sky</code> defaults to the same as <code>block</code>. Use <code>15, 15</code> for full-bright. Applies to every member (each passenger is its own entity).</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="block-1" tabindex="-1">block <a class="header-anchor" href="#block-1" aria-label="Permalink to &quot;block&quot;">​</a></h5><p><code>number</code></p><h5 id="sky" tabindex="-1">sky? <a class="header-anchor" href="#sky" aria-label="Permalink to &quot;sky?&quot;">​</a></h5><p><code>number</code> = <code>block</code></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="getname" tabindex="-1">getName() <a class="header-anchor" href="#getname" aria-label="Permalink to &quot;getName()&quot;">​</a></h3><blockquote><p><strong>getName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L227" target="_blank" rel="noreferrer">core/values/display.ts:227</a></p><p>The display&#39;s name/tag; throws if <a href="#named">named</a> was never called.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><hr><h3 id="getpivot" tabindex="-1">getPivot() <a class="header-anchor" href="#getpivot" aria-label="Permalink to &quot;getPivot()&quot;">​</a></h3><blockquote><p><strong>getPivot</strong>(): <a href="./../type-aliases/Vec3.html"><code>Vec3</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L210" target="_blank" rel="noreferrer">core/values/display.ts:210</a></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../type-aliases/Vec3.html"><code>Vec3</code></a></p><hr><h3 id="getpos" tabindex="-1">getPos() <a class="header-anchor" href="#getpos" aria-label="Permalink to &quot;getPos()&quot;">​</a></h3><blockquote><p><strong>getPos</strong>(): <code>string</code> | <a href="./PosValue.html"><code>PosValue</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L242" target="_blank" rel="noreferrer">core/values/display.ts:242</a></p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code> | <a href="./PosValue.html"><code>PosValue</code></a></p><hr><h3 id="hitbox" tabindex="-1">hitbox() <a class="header-anchor" href="#hitbox" aria-label="Permalink to &quot;hitbox()&quot;">​</a></h3><blockquote><p><strong>hitbox</strong>(<code>width?</code>, <code>height?</code>, <code>response?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L154" target="_blank" rel="noreferrer">core/values/display.ts:154</a></p><p>Give the group a <strong>hitbox</strong>. Display entities have none - nothing can hit them, and nothing can stand on them - so this rides an <code>interaction</code> entity on the root, which is the vanilla primitive that <em>does</em> have one: a cube <code>width</code> across and <code>height</code> tall that records the last attack/use in its own NBT (readable at <code>attack.player</code> / <code>interaction.player</code>).</p><p>Both default to the model&#39;s own <a href="#boundssize">boundsSize</a>. <code>response</code> (default <code>true</code>) is whether hitting it plays the hit sound / swings the arm.</p><p>Relaying that recorded hit onto a real mob is deliberately <em>not</em> here: it&#39;s a gameplay convention, so it belongs a layer up. This is the mechanism.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="width" tabindex="-1">width? <a class="header-anchor" href="#width" aria-label="Permalink to &quot;width?&quot;">​</a></h5><p><code>number</code></p><h5 id="height" tabindex="-1">height? <a class="header-anchor" href="#height" aria-label="Permalink to &quot;height?&quot;">​</a></h5><p><code>number</code></p><h5 id="response" tabindex="-1">response? <a class="header-anchor" href="#response" aria-label="Permalink to &quot;response?&quot;">​</a></h5><p><code>boolean</code> = <code>true</code></p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="hitboxselector" tabindex="-1">hitboxSelector() <a class="header-anchor" href="#hitboxselector" aria-label="Permalink to &quot;hitboxSelector()&quot;">​</a></h3><blockquote><p><strong>hitboxSelector</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L164" target="_blank" rel="noreferrer">core/values/display.ts:164</a></p><p>A selector for the hitbox alone - what an attack-relay reads.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><hr><h3 id="interpolation" tabindex="-1">interpolation() <a class="header-anchor" href="#interpolation" aria-label="Permalink to &quot;interpolation()&quot;">​</a></h3><blockquote><p><strong>interpolation</strong>(<code>ticks</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L176" target="_blank" rel="noreferrer">core/values/display.ts:176</a></p><p>Tween transform changes over <code>ticks</code> instead of snapping to them. Display entities don&#39;t interpolate for free: the duration is stored <strong>on the entity</strong> and every later update has to re-trigger it (<code>start_interpolation</code>), which is what the clip engine&#39;s transform writes already do - this sets the resting default so an ad-hoc <code>data merge</code> moves smoothly too.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ticks" tabindex="-1">ticks <a class="header-anchor" href="#ticks" aria-label="Permalink to &quot;ticks&quot;">​</a></h5><p><code>number</code></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="kill" tabindex="-1">kill() <a class="header-anchor" href="#kill" aria-label="Permalink to &quot;kill()&quot;">​</a></h3><blockquote><p><strong>kill</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L273" target="_blank" rel="noreferrer">core/values/display.ts:273</a></p><p>Remove every member of the group.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx" tabindex="-1">ctx <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="members" tabindex="-1">members() <a class="header-anchor" href="#members" aria-label="Permalink to &quot;members()&quot;">​</a></h3><blockquote><p><strong>members</strong>(): <a href="./../interfaces/DisplayChild.html"><code>DisplayChild</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L282" target="_blank" rel="noreferrer">core/values/display.ts:282</a></p><p>Ordered members - root first (index 0), then the added children. The hitbox is <strong>not</strong> one: it carries no transform, so nothing that animates members should ever address it.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/DisplayChild.html"><code>DisplayChild</code></a>[]</p><hr><h3 id="named" tabindex="-1">named() <a class="header-anchor" href="#named" aria-label="Permalink to &quot;named()&quot;">​</a></h3><blockquote><p><strong>named</strong>(<code>name</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L221" target="_blank" rel="noreferrer">core/values/display.ts:221</a></p><p>Give the display an identity. Every member is tagged <code>Tags:[&quot;&lt;name&gt;&quot;, &quot;&lt;name&gt;_&lt;i&gt;&quot;]</code> (root is index 0), so the whole group is addressable by <code>@e[tag=&lt;name&gt;]</code> and each member by <code>@e[tag=&lt;name&gt;_&lt;i&gt;]</code>. Required before summoning/killing/animating. Unnamed displays render with no tags (static packs stay byte-identical).</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="pivot" tabindex="-1">pivot() <a class="header-anchor" href="#pivot" aria-label="Permalink to &quot;pivot()&quot;">​</a></h3><blockquote><p><strong>pivot</strong>(<code>p</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L205" target="_blank" rel="noreferrer">core/values/display.ts:205</a></p><p>Set the local-space pivot the group rotates about (default origin).</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="p" tabindex="-1">p <a class="header-anchor" href="#p" aria-label="Permalink to &quot;p&quot;">​</a></h5><p><a href="./../type-aliases/Vec3.html"><code>Vec3</code></a></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="render" tabindex="-1">render() <a class="header-anchor" href="#render" aria-label="Permalink to &quot;render()&quot;">​</a></h3><blockquote><p><strong>render</strong>(<code>version</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L365" target="_blank" rel="noreferrer">core/values/display.ts:365</a></p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="version" tabindex="-1">version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;version&quot;">​</a></h5><p><a href="./../interfaces/VersionProfile.html"><code>VersionProfile</code></a></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><h4 id="implementation-of" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of" aria-label="Permalink to &quot;Implementation of&quot;">​</a></h4><p><a href="./../interfaces/CommandValue.html"><code>CommandValue</code></a>.<a href="./../interfaces/CommandValue.html#render"><code>render</code></a></p><hr><h3 id="selector" tabindex="-1">selector() <a class="header-anchor" href="#selector" aria-label="Permalink to &quot;selector()&quot;">​</a></h3><blockquote><p><strong>selector</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L247" target="_blank" rel="noreferrer">core/values/display.ts:247</a></p><p>A selector matching the whole group: <code>@e[tag=&lt;name&gt;]</code>.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><hr><h3 id="setblock" tabindex="-1">setBlock() <a class="header-anchor" href="#setblock" aria-label="Permalink to &quot;setBlock()&quot;">​</a></h3><blockquote><p><strong>setBlock</strong>(<code>block</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L111" target="_blank" rel="noreferrer">core/values/display.ts:111</a></p><p>Replace the root member with a block.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="block-2" tabindex="-1">block <a class="header-anchor" href="#block-2" aria-label="Permalink to &quot;block&quot;">​</a></h5><p><a href="./BlockValue.html"><code>BlockValue</code></a></p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="setitem" tabindex="-1">setItem() <a class="header-anchor" href="#setitem" aria-label="Permalink to &quot;setItem()&quot;">​</a></h3><blockquote><p><strong>setItem</strong>(<code>item</code>, <code>context?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L117" target="_blank" rel="noreferrer">core/values/display.ts:117</a></p><p>Replace the root member with an item.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="item-1" tabindex="-1">item <a class="header-anchor" href="#item-1" aria-label="Permalink to &quot;item&quot;">​</a></h5><p><a href="./ItemValue.html"><code>ItemValue</code></a></p><h5 id="context-1" tabindex="-1">context? <a class="header-anchor" href="#context-1" aria-label="Permalink to &quot;context?&quot;">​</a></h5><p><a href="./../type-aliases/NbtInput.html"><code>NbtInput</code></a></p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="summon" tabindex="-1">summon() <a class="header-anchor" href="#summon" aria-label="Permalink to &quot;summon()&quot;">​</a></h3><blockquote><p><strong>summon</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L262" target="_blank" rel="noreferrer">core/values/display.ts:262</a></p><p>Summon the display at its <a href="#at">at</a> position.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-1" tabindex="-1">ctx <a class="header-anchor" href="#ctx-1" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="summonif" tabindex="-1">summonIf() <a class="header-anchor" href="#summonif" aria-label="Permalink to &quot;summonIf()&quot;">​</a></h3><blockquote><p><strong>summonIf</strong>(<code>ctx</code>, <code>cond</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L268" target="_blank" rel="noreferrer">core/values/display.ts:268</a></p><p>Summon the display only when <code>cond</code> holds (e.g. <code>cog.notExist</code>).</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-2" tabindex="-1">ctx <a class="header-anchor" href="#ctx-2" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h5 id="cond" tabindex="-1">cond <a class="header-anchor" href="#cond" aria-label="Permalink to &quot;cond&quot;">​</a></h5><p><a href="./../interfaces/EntityCondition.html"><code>EntityCondition</code></a></p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="teleportduration" tabindex="-1">teleportDuration() <a class="header-anchor" href="#teleportduration" aria-label="Permalink to &quot;teleportDuration()&quot;">​</a></h3><blockquote><p><strong>teleportDuration</strong>(<code>ticks</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L187" target="_blank" rel="noreferrer">core/values/display.ts:187</a></p><p>Glide over <code>ticks</code> when <strong>teleported</strong> rather than jumping. Separate from <a href="#interpolation">interpolation</a> in vanilla (transform tweening and positional tweening are different fields), and the one that matters for a model being moved around by <code>tp</code> - a boss rig following its mob, say.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ticks-1" tabindex="-1">ticks <a class="header-anchor" href="#ticks-1" aria-label="Permalink to &quot;ticks&quot;">​</a></h5><p><code>number</code></p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="tonbt" tabindex="-1">toNbt() <a class="header-anchor" href="#tonbt" aria-label="Permalink to &quot;toNbt()&quot;">​</a></h3><blockquote><p><strong>toNbt</strong>(): <a href="./../interfaces/IdentifiedEntityNbt.html"><code>IdentifiedEntityNbt</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/helix/src/core/values/display.ts#L317" target="_blank" rel="noreferrer">core/values/display.ts:317</a></p><p>The typed <code>block_display</code> NBT this summons as - root first, children as <code>passengers</code>. Built through the entity&#39;s own schema, so the key spellings and SNBT suffixes are the compiler&#39;s business, not this file&#39;s.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/IdentifiedEntityNbt.html"><code>IdentifiedEntityNbt</code></a></p>',274)])])}const b=a(s,[["render",i]]);export{p as __pageData,b as default};
